// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IHook{function tokensReceived() external;} contract HookToken {mapping(address=>uint) public balance;function send(address to,uint amount) external {balance[msg.sender]-=amount;IHook(to).tokensReceived();balance[to]+=amount;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IHook2{function tokensReceived() external;} contract CEIToken {mapping(address=>uint) public balance;function send(address to,uint amount) external {balance[msg.sender]-=amount;balance[to]+=amount;IHook2(to).tokensReceived();} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IERC20A{function transferFrom(address,address,uint) external returns(bool);} contract FeeMismatch {IERC20A public token;mapping(address=>uint) public credit;function deposit(uint amount) external {require(token.transferFrom(msg.sender,address(this),amount));credit[msg.sender]+=amount;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IERC20B{function transferFrom(address,address,uint) external returns(bool);function balanceOf(address) external view returns(uint);} contract BalanceDelta {IERC20B public token;mapping(address=>uint) public credit;function deposit(uint amount) external {uint b=token.balanceOf(address(this));require(token.transferFrom(msg.sender,address(this),amount));uint got=token.balanceOf(address(this))-b;credit[msg.sender]+=got;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract BlacklistBypass {mapping(address=>bool) public blocked;mapping(address=>uint) public balance;function transfer(address to,uint a) external {require(!blocked[msg.sender]);balance[msg.sender]-=a;balance[to]+=a;}function adminMove(address from,address to,uint a) external {balance[from]-=a;balance[to]+=a;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract PolicyConsistent {mapping(address=>bool) public blocked;mapping(address=>uint) public balance;address public owner;constructor(){owner=msg.sender;}function move(address from,address to,uint a) public {require(!blocked[from]&&!blocked[to]);require(msg.sender==from||msg.sender==owner);balance[from]-=a;balance[to]+=a;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract NoPause {mapping(address=>uint) public debt;function borrow(uint a) external {debt[msg.sender]+=a;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract PausableSystem {bool public paused;address public owner;mapping(address=>uint) public debt;constructor(){owner=msg.sender;}function setPaused(bool v) external {require(msg.sender==owner);paused=v;}function borrow(uint a) external {require(!paused);debt[msg.sender]+=a;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract InsolventWithdraw {mapping(address=>uint) public collateral;mapping(address=>uint) public debt;function withdraw(uint a) external {collateral[msg.sender]-=a;payable(msg.sender).transfer(a);}receive() external payable{} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract SolvencyGuard {mapping(address=>uint) public collateral;mapping(address=>uint) public debt;function withdraw(uint a) external {require(collateral[msg.sender]-a>=debt[msg.sender]*2);collateral[msg.sender]-=a;payable(msg.sender).transfer(a);}receive() external payable{} }
